def compute_r_derivs_case2(r, S, R_probe):
    """
    Compute dI/dr through d6I/dr6 for Case 2 (l = 1/(r-S)).

    Parameters
    ----------
    r : float or ndarray
        Distance(s) from grid point to receptor atom
    S : float
        Scaled receptor radius
    R_probe : float
        Probe radius (used in log term)

    Returns
    -------
    tuple of 7 arrays: (I0, I1, I2, I3, I4, I5, I6)
    """
    # Precompute common terms
    rps = r + S  # r + S
    rms = r - S  # r - S

    rps2 = rps * rps
    rps3 = rps2 * rps
    rps4 = rps3 * rps
    rps5 = rps4 * rps
    rps6 = rps5 * rps
    rps7 = rps6 * rps
    rps8 = rps7 * rps

    rms2 = rms * rms
    rms3 = rms2 * rms
    rms4 = rms3 * rms
    rms5 = rms4 * rms
    rms6 = rms5 * rms
    rms7 = rms6 * rms
    rms8 = rms7 * rms

    r2 = r * r
    r3 = r2 * r
    r4 = r3 * r
    r5 = r4 * r
    r6 = r5 * r
    r7 = r6 * r

    S2 = S * S
    S4 = S2 * S2
    S6 = S4 * S2

    u = 1.0 / rps
    l = 1.0 / rms

    I0 = S**2*(-1/(S + r)**2 + (-S + r)**(-2))/(4*r) + r*((S + r)**(-2) - 1/(-S + r)**2)/4 - 1/(S + r) + 1/(-S + r) + np.log((-S + r)/(S + r))/(2*r)
    I1 = (-S**4*np.log(-S + r) - 2*S**3*r + 2*S**2*r**2*np.log(-S + r) - 2*S*r**3 - r**4*np.log(-S + r) + np.log((S + r)**(S**4 - 2*S**2*r**2 + r**4)))/(2*r**2*(S**4 - 2*S**2*r**2 + r**4))
    I2 = (-S**6*np.log(-S + r) - 2*S**5*r + 3*S**4*r**2*np.log(-S + r) + 8*S**3*r**3 - 3*S**2*r**4*np.log(-S + r) + 2*S*r**5 + r**6*np.log(-S + r) + np.log((S + r)**(S**6 - 3*S**4*r**2 + 3*S**2*r**4 - r**6)))/(r**3*(-S**6 + 3*S**4*r**2 - 3*S**2*r**4 + r**6))
    I3 = (-3*S**8*np.log(-S + r) - 6*S**7*r + 12*S**6*r**2*np.log(-S + r) + 22*S**5*r**3 - 18*S**4*r**4*np.log(-S + r) - 58*S**3*r**5 + 12*S**2*r**6*np.log(-S + r) - 6*S*r**7 - 3*r**8*np.log(-S + r) + np.log((S + r)**(3*S**8 - 12*S**6*r**2 + 18*S**4*r**4 - 12*S**2*r**6 + 3*r**8)))/(r**4*(S**8 - 4*S**6*r**2 + 6*S**4*r**4 - 4*S**2*r**6 + r**8))
    I4 = 4*(-3*S**10*np.log(-S + r) - 6*S**9*r + 15*S**8*r**2*np.log(-S + r) + 28*S**7*r**3 - 30*S**6*r**4*np.log(-S + r) - 44*S**5*r**5 + 30*S**4*r**6*np.log(-S + r) + 112*S**3*r**7 - 15*S**2*r**8*np.log(-S + r) + 6*S*r**9 + 3*r**10*np.log(-S + r) + np.log((S + r)**(3*S**10 - 15*S**8*r**2 + 30*S**6*r**4 - 30*S**4*r**6 + 15*S**2*r**8 - 3*r**10)))/(r**5*(-S**10 + 5*S**8*r**2 - 10*S**6*r**4 + 10*S**4*r**6 - 5*S**2*r**8 + r**10))
    I5 = 4*(-15*S**12*np.log(-S + r) - 30*S**11*r + 90*S**10*r**2*np.log(-S + r) + 170*S**9*r**3 - 225*S**8*r**4*np.log(-S + r) - 396*S**7*r**5 + 300*S**6*r**6*np.log(-S + r) + 276*S**5*r**7 - 225*S**4*r**8*np.log(-S + r) - 950*S**3*r**9 + 90*S**2*r**10*np.log(-S + r) - 30*S*r**11 - 15*r**12*np.log(-S + r) + np.log((S + r)**(15*S**12 - 90*S**10*r**2 + 225*S**8*r**4 - 300*S**6*r**6 + 225*S**4*r**8 - 90*S**2*r**10 + 15*r**12)))/(r**6*(S**12 - 6*S**10*r**2 + 15*S**8*r**4 - 20*S**6*r**6 + 15*S**4*r**8 - 6*S**2*r**10 + r**12))
    I6 = 24*(-15*S**14*np.log(-S + r) - 30*S**13*r + 105*S**12*r**2*np.log(-S + r) + 200*S**11*r**3 - 315*S**10*r**4*np.log(-S + r) - 566*S**9*r**5 + 525*S**8*r**6*np.log(-S + r) + 912*S**7*r**7 - 525*S**6*r**8*np.log(-S + r) - 106*S**5*r**9 + 315*S**4*r**10*np.log(-S + r) + 1480*S**3*r**11 - 105*S**2*r**12*np.log(-S + r) + 30*S*r**13 + 15*r**14*np.log(-S + r) + np.log((S + r)**(15*S**14 - 105*S**12*r**2 + 315*S**10*r**4 - 525*S**8*r**6 + 525*S**6*r**8 - 315*S**4*r**10 + 105*S**2*r**12 - 15*r**14)))/(r**7*(-S**14 + 7*S**12*r**2 - 21*S**10*r**4 + 35*S**8*r**6 - 35*S**6*r**8 + 21*S**4*r**10 - 7*S**2*r**12 + r**14))

    return I0, I1, I2, I3, I4, I5, I6


def apply_chain_rule_tricubic(I0, I1, I2, I3, nx, ny, nz, r):
    """
    Apply chain rule to convert r-derivatives to Cartesian derivatives for tricubic.

    Parameters
    ----------
    I0, I1, I2, I3 : float or ndarray
        I(r) and its derivatives w.r.t. r
    nx, ny, nz : float or ndarray
        Direction cosines (dx/r, dy/r, dz/r)
    r : float or ndarray
        Distance

    Returns
    -------
    derivs : ndarray of shape (8,) or (8, N)
        [f, fx, fy, fz, fxy, fxz, fyz, fxyz]
    """
    scalar = np.isscalar(r)
    if scalar:
        derivs = np.zeros(8)
    else:
        derivs = np.zeros((8, len(np.atleast_1d(r))))

    # f = I0
    derivs[0] = I0

    # fx = I1 * nx
    derivs[1] = I1 * nx

    # fy = I1 * ny
    derivs[2] = I1 * ny

    # fz = I1 * nz
    derivs[3] = I1 * nz

    # fxy = nx*ny*(I2 - I1/r)
    derivs[4] = nx * ny * (I2 - I1/r)

    # fxz = nx*nz*(I2 - I1/r)
    derivs[5] = nx * nz * (I2 - I1/r)

    # fyz = ny*nz*(I2 - I1/r)
    derivs[6] = ny * nz * (I2 - I1/r)

    # fxyz = nx*ny*nz*(I3 - 3*I2/r + 3*I1/r^2)
    derivs[7] = nx * ny * nz * (I3 - 3*I2/r + 3*I1/r**2)

    return derivs


def apply_chain_rule_triquintic(I0, I1, I2, I3, I4, I5, I6, nx, ny, nz, r):
    """
    Apply chain rule to convert r-derivatives to Cartesian derivatives for triquintic.

    Parameters
    ----------
    I0 through I6 : float or ndarray
        I(r) and its derivatives w.r.t. r up to 6th order
    nx, ny, nz : float or ndarray
        Direction cosines (dx/r, dy/r, dz/r)
    r : float or ndarray
        Distance

    Returns
    -------
    derivs : ndarray of shape (27,) or (27, N)
        All 27 RASPA3 derivatives
    """
    scalar = np.isscalar(r)
    if scalar:
        derivs = np.zeros(27)
    else:
        derivs = np.zeros((27, len(np.atleast_1d(r))))

    # Precompute powers
    r2 = r * r
    r3 = r2 * r
    r4 = r3 * r
    r5 = r4 * r
    r6 = r5 * r

    nx2 = nx * nx
    ny2 = ny * ny
    nz2 = nz * nz

    nx3 = nx2 * nx
    ny3 = ny2 * ny
    nz3 = nz2 * nz

    nx4 = nx2 * nx2
    ny4 = ny2 * ny2
    nz4 = nz2 * nz2

    # f
    derivs[0] = I0

    # fx
    derivs[1] = I1*nx

    # fy
    derivs[2] = I1*ny

    # fz
    derivs[3] = I1*nz

    # fxx
    derivs[4] = (-I1*(nx**2 - 1) + I2*nx**2*r)/r

    # fxy
    derivs[5] = nx*ny*(-I1 + I2*r)/r

    # fxz
    derivs[6] = nx*nz*(-I1 + I2*r)/r

    # fyy
    derivs[7] = (-I1*(ny**2 - 1) + I2*ny**2*r)/r

    # fyz
    derivs[8] = ny*nz*(-I1 + I2*r)/r

    # fzz
    derivs[9] = (-I1*(nz**2 - 1) + I2*nz**2*r)/r

    # fxxy
    derivs[10] = ny*(3*I1*nx**2 - I1 - 3*I2*nx**2*r + I2*r + I3*nx**2*r**2)/r**2

    # fxxz
    derivs[11] = nz*(3*I1*nx**2 - I1 - 3*I2*nx**2*r + I2*r + I3*nx**2*r**2)/r**2

    # fxyy
    derivs[12] = nx*(3*I1*ny**2 - I1 - 3*I2*ny**2*r + I2*r + I3*ny**2*r**2)/r**2

    # fxyz
    derivs[13] = nx*ny*nz*(3*I1 - 3*I2*r + I3*r**2)/r**2

    # fyyz
    derivs[14] = nz*(3*I1*ny**2 - I1 - 3*I2*ny**2*r + I2*r + I3*ny**2*r**2)/r**2

    # fxzz
    derivs[15] = nx*(3*I1*nz**2 - I1 - 3*I2*nz**2*r + I2*r + I3*nz**2*r**2)/r**2

    # fyzz
    derivs[16] = ny*(3*I1*nz**2 - I1 - 3*I2*nz**2*r + I2*r + I3*nz**2*r**2)/r**2

    # fxxyy
    derivs[17] = (-15*I1*nx**2*ny**2 + 3*I1*nx**2 + 3*I1*ny**2 - I1 + 15*I2*nx**2*ny**2*r - 3*I2*nx**2*r - 3*I2*ny**2*r + I2*r - 6*I3*nx**2*ny**2*r**2 + I3*nx**2*r**2 + I3*ny**2*r**2 + I4*nx**2*ny**2*r**3)/r**3

    # fxxzz
    derivs[18] = (-15*I1*nx**2*nz**2 + 3*I1*nx**2 + 3*I1*nz**2 - I1 + 15*I2*nx**2*nz**2*r - 3*I2*nx**2*r - 3*I2*nz**2*r + I2*r - 6*I3*nx**2*nz**2*r**2 + I3*nx**2*r**2 + I3*nz**2*r**2 + I4*nx**2*nz**2*r**3)/r**3

    # fyyzz
    derivs[19] = (-15*I1*ny**2*nz**2 + 3*I1*ny**2 + 3*I1*nz**2 - I1 + 15*I2*ny**2*nz**2*r - 3*I2*ny**2*r - 3*I2*nz**2*r + I2*r - 6*I3*ny**2*nz**2*r**2 + I3*ny**2*r**2 + I3*nz**2*r**2 + I4*ny**2*nz**2*r**3)/r**3

    # fxxyz
    derivs[20] = ny*nz*(-15*I1*nx**2 + 3*I1 + 15*I2*nx**2*r - 3*I2*r - 6*I3*nx**2*r**2 + I3*r**2 + I4*nx**2*r**3)/r**3

    # fxyyz
    derivs[21] = nx*nz*(-15*I1*ny**2 + 3*I1 + 15*I2*ny**2*r - 3*I2*r - 6*I3*ny**2*r**2 + I3*r**2 + I4*ny**2*r**3)/r**3

    # fxyzz
    derivs[22] = nx*ny*(-15*I1*nz**2 + 3*I1 + 15*I2*nz**2*r - 3*I2*r - 6*I3*nz**2*r**2 + I3*r**2 + I4*nz**2*r**3)/r**3

    # fxxyyz
    derivs[23] = nz*(105*I1*nx**2*ny**2 - 15*I1*nx**2 - 15*I1*ny**2 + 3*I1 - 105*I2*nx**2*ny**2*r + 15*I2*nx**2*r + 15*I2*ny**2*r - 3*I2*r + 45*I3*nx**2*ny**2*r**2 - 6*I3*nx**2*r**2 - 6*I3*ny**2*r**2 + I3*r**2 - 10*I4*nx**2*ny**2*r**3 + I4*nx**2*r**3 + I4*ny**2*r**3 + I5*nx**2*ny**2*r**4)/r**4

    # fxxyzz
    derivs[24] = ny*(105*I1*nx**2*nz**2 - 15*I1*nx**2 - 15*I1*nz**2 + 3*I1 - 105*I2*nx**2*nz**2*r + 15*I2*nx**2*r + 15*I2*nz**2*r - 3*I2*r + 45*I3*nx**2*nz**2*r**2 - 6*I3*nx**2*r**2 - 6*I3*nz**2*r**2 + I3*r**2 - 10*I4*nx**2*nz**2*r**3 + I4*nx**2*r**3 + I4*nz**2*r**3 + I5*nx**2*nz**2*r**4)/r**4

    # fxyyzz
    derivs[25] = nx*(105*I1*ny**2*nz**2 - 15*I1*ny**2 - 15*I1*nz**2 + 3*I1 - 105*I2*ny**2*nz**2*r + 15*I2*ny**2*r + 15*I2*nz**2*r - 3*I2*r + 45*I3*ny**2*nz**2*r**2 - 6*I3*ny**2*r**2 - 6*I3*nz**2*r**2 + I3*r**2 - 10*I4*ny**2*nz**2*r**3 + I4*ny**2*r**3 + I4*nz**2*r**3 + I5*ny**2*nz**2*r**4)/r**4

    # fxxyyzz
    derivs[26] = (-945*I1*nx**2*ny**2*nz**2 + 105*I1*nx**2*ny**2 + 105*I1*nx**2*nz**2 - 15*I1*nx**2 + 105*I1*ny**2*nz**2 - 15*I1*ny**2 - 15*I1*nz**2 + 3*I1 + 945*I2*nx**2*ny**2*nz**2*r - 105*I2*nx**2*ny**2*r - 105*I2*nx**2*nz**2*r + 15*I2*nx**2*r - 105*I2*ny**2*nz**2*r + 15*I2*ny**2*r + 15*I2*nz**2*r - 3*I2*r - 420*I3*nx**2*ny**2*nz**2*r**2 + 45*I3*nx**2*ny**2*r**2 + 45*I3*nx**2*nz**2*r**2 - 6*I3*nx**2*r**2 + 45*I3*ny**2*nz**2*r**2 - 6*I3*ny**2*r**2 - 6*I3*nz**2*r**2 + I3*r**2 + 105*I4*nx**2*ny**2*nz**2*r**3 - 10*I4*nx**2*ny**2*r**3 - 10*I4*nx**2*nz**2*r**3 + I4*nx**2*r**3 - 10*I4*ny**2*nz**2*r**3 + I4*ny**2*r**3 + I4*nz**2*r**3 - 15*I5*nx**2*ny**2*nz**2*r**4 + I5*nx**2*ny**2*r**4 + I5*nx**2*nz**2*r**4 + I5*ny**2*nz**2*r**4 + I6*nx**2*ny**2*nz**2*r**5)/r**5

    return derivs


def compute_hct_derivs_tricubic(dx, dy, dz, S, R_probe):
    """
    Compute tricubic HCT derivatives (8 values).

    Parameters
    ----------
    dx, dy, dz : float or ndarray
        Displacement from receptor atom to grid point
    S : float
        Scaled receptor radius
    R_probe : float
        Probe radius

    Returns
    -------
    derivs : ndarray of shape (8,) or (8, N)
        [f, fx, fy, fz, fxy, fxz, fyz, fxyz]
    """
    r = np.sqrt(dx**2 + dy**2 + dz**2)
    nx = dx / r
    ny = dy / r
    nz = dz / r

    crossover = np.abs(r - S)

    if np.isscalar(r):
        if R_probe > crossover:
            I0, I1, I2, I3, _, _, _ = compute_r_derivs_case1(r, S, R_probe)
        else:
            I0, I1, I2, I3, _, _, _ = compute_r_derivs_case2(r, S, R_probe)
        return apply_chain_rule_tricubic(I0, I1, I2, I3, nx, ny, nz, r)
    else:
        # Vectorized case
        derivs = np.zeros((8, len(r)))

        case1_mask = R_probe > crossover
        case2_mask = ~case1_mask

        if np.any(case1_mask):
            I0, I1, I2, I3, _, _, _ = compute_r_derivs_case1(r[case1_mask], S, R_probe)
            d = apply_chain_rule_tricubic(I0, I1, I2, I3,
                                          nx[case1_mask], ny[case1_mask], nz[case1_mask],
                                          r[case1_mask])
            derivs[:, case1_mask] = d

        if np.any(case2_mask):
            I0, I1, I2, I3, _, _, _ = compute_r_derivs_case2(r[case2_mask], S, R_probe)
            d = apply_chain_rule_tricubic(I0, I1, I2, I3,
                                          nx[case2_mask], ny[case2_mask], nz[case2_mask],
                                          r[case2_mask])
            derivs[:, case2_mask] = d

        return derivs


def compute_hct_derivs_triquintic(dx, dy, dz, S, R_probe):
    """
    Compute triquintic HCT derivatives (27 values).

    Parameters
    ----------
    dx, dy, dz : float or ndarray
        Displacement from receptor atom to grid point
    S : float
        Scaled receptor radius
    R_probe : float
        Probe radius

    Returns
    -------
    derivs : ndarray of shape (27,) or (27, N)
        All RASPA3 derivatives
    """
    r = np.sqrt(dx**2 + dy**2 + dz**2)
    nx = dx / r
    ny = dy / r
    nz = dz / r

    crossover = np.abs(r - S)

    if np.isscalar(r):
        if R_probe > crossover:
            I0, I1, I2, I3, I4, I5, I6 = compute_r_derivs_case1(r, S, R_probe)
        else:
            I0, I1, I2, I3, I4, I5, I6 = compute_r_derivs_case2(r, S, R_probe)
        return apply_chain_rule_triquintic(I0, I1, I2, I3, I4, I5, I6, nx, ny, nz, r)
    else:
        # Vectorized case
        derivs = np.zeros((27, len(r)))

        case1_mask = R_probe > crossover
        case2_mask = ~case1_mask

        if np.any(case1_mask):
            I_all = compute_r_derivs_case1(r[case1_mask], S, R_probe)
            d = apply_chain_rule_triquintic(*I_all,
                                            nx[case1_mask], ny[case1_mask], nz[case1_mask],
                                            r[case1_mask])
            derivs[:, case1_mask] = d

        if np.any(case2_mask):
            I_all = compute_r_derivs_case2(r[case2_mask], S, R_probe)
            d = apply_chain_rule_triquintic(*I_all,
                                            nx[case2_mask], ny[case2_mask], nz[case2_mask],
                                            r[case2_mask])
            derivs[:, case2_mask] = d

        return derivs


if __name__ == '__main__':
    # Validation test
    print("Testing HCT analytical derivatives...")

    dx, dy, dz = 0.3, 0.2, 0.15
    r = np.sqrt(dx**2 + dy**2 + dz**2)
    S = 0.15
    R_probe = 0.131

    crossover = abs(r - S)
    print(f"r={r:.4f}, S={S}, R_probe={R_probe}")
    print(f"Crossover |r-S| = {crossover:.4f}")
    print(f"Case: {'1 (R_probe > |r-S|)' if R_probe > crossover else '2 (R_probe <= |r-S|)'}")

    # Test tricubic
    print("\nTricubic derivatives:")
    derivs8 = compute_hct_derivs_tricubic(dx, dy, dz, S, R_probe)
    for i, name in enumerate(TRICUBIC_NAMES):
        print(f"  {name}: {derivs8[i]:.10e}")

    # Test triquintic
    print("\nTriquintic derivatives:")
    derivs27 = compute_hct_derivs_triquintic(dx, dy, dz, S, R_probe)
    for i, name in enumerate(RASPA3_NAMES):
        print(f"  {name}: {derivs27[i]:.10e}")

    # Numerical gradient check
    print("\nNumerical gradient check (fx, fy, fz):")
    h = 1e-6

    for dim, label in enumerate(['x', 'y', 'z']):
        dx_p = dx + h if dim == 0 else dx
        dy_p = dy + h if dim == 1 else dy
        dz_p = dz + h if dim == 2 else dz
        dx_m = dx - h if dim == 0 else dx
        dy_m = dy - h if dim == 1 else dy
        dz_m = dz - h if dim == 2 else dz

        f_p = compute_hct_derivs_tricubic(dx_p, dy_p, dz_p, S, R_probe)[0]
        f_m = compute_hct_derivs_tricubic(dx_m, dy_m, dz_m, S, R_probe)[0]

        fd = (f_p - f_m) / (2 * h)
        analytical = derivs8[dim + 1]
        print(f"  f{label}: analytical={analytical:.10e}, FD={fd:.10e}, diff={abs(fd-analytical):.2e}")
